logging {
  level  = "info"
  format = "logfmt"
}

discovery.kubernetes "pods" {
  role = "pod"
  selectors {
    role  = "pod"
    field = "spec.nodeName=" + env("NODE_NAME")
  }
}

discovery.relabel "pods" {
  targets = discovery.kubernetes.pods.targets
  // Drop kube-system pods to conserve quota
  rule {
    action        = "drop"
    source_labels = ["__meta_kubernetes_namespace"]
    regex         = "kube-system"
  }
  // instance = node hostname (aligns with host agents)
  rule {
    action        = "replace"
    source_labels = ["__meta_kubernetes_pod_node_name"]
    target_label  = "instance"
  }
  rule {
    action        = "replace"
    source_labels = ["__meta_kubernetes_pod_label_app_kubernetes_io_name"]
    target_label  = "app"
  }
  rule {
    action        = "replace"
    source_labels = ["__meta_kubernetes_namespace"]
    target_label  = "namespace"
  }
  rule {
    action        = "replace"
    source_labels = ["__meta_kubernetes_pod_name"]
    target_label  = "pod"
  }
  rule {
    action        = "replace"
    source_labels = ["__meta_kubernetes_pod_container_name"]
    target_label  = "container"
  }
}

loki.source.kubernetes "pods" {
  targets    = discovery.relabel.pods.output
  forward_to = [loki.process.pods.receiver]
}

loki.process "pods" {
  forward_to = [loki.write.grafana_cloud.receiver]
  stage.json {
    expressions = { level = "level" }
  }
  stage.labels {
    values = { level = "" }
  }
  stage.drop {
    older_than          = "1h"
    drop_counter_reason = "too_old"
  }
}

loki.write "grafana_cloud" {
  endpoint {
    url        = env("GRAFANA_CLOUD_LOKI_URL")
    basic_auth {
      username = env("GRAFANA_CLOUD_LOKI_USERNAME")
      password = env("GRAFANA_CLOUD_LOKI_PASSWORD")
    }
    batch_wait         = "5s"
    min_backoff_period = "2s"
  }
  external_labels = {
    cluster = "xenu",
  }
}
